-- Authorized PHILVIEWS #14 and #15 production catalog import.
-- Source records: 85 + 61 = 146. This transaction touches only catalog and
-- participating Publisher records. It intentionally does not touch customers,
-- orders, payments, shipments, returns, credentials, or files.

begin;

do $$
begin
  if (select count(*) from public.titles) <> 0
     or (select count(*) from public.catalog_cycles) <> 0
     or (select count(*) from public.catalog_publication_items) <> 0
     or (select count(*) from public.catalog_import_batches) <> 0 then
    raise exception 'Catalog import stopped: production catalog tables are no longer empty.';
  end if;
  if (select count(*) from public.organizations where id in ('3811302a-dd82-4a06-985b-35afe4957c17', '82028526-e6a8-42b8-b26e-86cfb9e991a8', 'ac704c8e-e112-468b-ad57-48be22ffadc8', 'af0a46f8-e54b-4452-aac4-3a689188ec39', '33f59355-02ed-4859-874e-9e51e33e131d', '28bec1a4-b2a2-494b-9719-81b396305e58', 'b742240d-17d7-48ad-9477-dbd192326faf', '3c0724de-8fff-494c-98a4-0a6cfba76841', 'b774447e-2ec1-4d57-bd06-98bea11d2b3e', 'e64181b7-a440-4f0c-b694-a6e3c7a56b96', '1a54e853-79c1-4e38-b127-e5ad18be31ef', '6918da47-bb9a-4019-9a4e-5fe0ffaaf61a', 'cccd6967-e9ad-4d20-8588-d7997ca76c26', 'c641d442-8d1a-49c3-8f7e-ebd082b33621', 'f443d302-f378-4a30-b4c7-0a2bc9a37c7a', '2e2ddf1e-099c-45ce-b62d-049d01667d81', '02466c1d-4e5a-4d57-908d-c7ff97599d91')) <> 17 then
    raise exception 'Catalog import stopped: the 17 reviewed September Publisher UUIDs are not intact.';
  end if;
  if (select count(*) from public.profiles where lower(email) = lower('mauramariepowers+retailer@gmail.com')) <> 1 then
    raise exception 'Catalog import stopped: the authorized production profile was not found exactly once.';
  end if;
end
$$;

