  ('81f6b73d-b45a-4265-b682-9ad58ceaaae2', 'f14321f4-f7a0-4a43-8432-88ef70e78d78', '14000000-0000-4000-8000-000000000014', 'PHI-111126-206', '9031274526', 'Powerscape Issue #2', 'Powerscape', '2', null, 'Cover Art by Pia Guerra', 'English', 'Standard Floppy Comic', 'Ongoing', 'PWRSCP', 'Quarterly', 'T – Teen 13+', 700, 'In the unlivable climate of the 28th century, Earth''s remaining cities are now governed by sports franchises, fronting superpowered players who compete for the extraterrestrial energy that fuels their city''s artificial atmospheres. But when a climate refugee becomes New Caledonia''s surprise breakout player, the intricate political systems off the field begin to show themselves, leading to an ultimate referendum on the last game of humanity. Written by Donal Thoms-Cappello. Art by Stefan Tosheff. Additional art by Cindy Leong, Rasheed Banda.', 'Thrown into her first game, first year "rook" Gela Gale tries to help the Stargazers win enough energy to keep New Caledonia powered against the scrappy Lone Twin City Beacons, featuring the camouflaging Blanc, the nature-controlling Timber, and their Team Captain, the powerful half-alien known as Alpha Beta. Art by Stefan Tosheff, with cover art by Pia Guerra (Y: The Last Man). Written by Donal Thoms-Cappello, lettering by Jeffrey Ellis, additional art by Rasheed Banda and Cindy Leong.', 'Donal Thoms-Cappello', 'Stefan Tosheff', 'Pia Guerra', 'CGN000000', 'CGN013000', 'CGN004400', 24, 'Full Color', 6.75, 10.5, 8, false, 1, true, 'Action/Sci-Fi/Superhero', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor), (select user_id from pg_temp.philbo_import_actor), '14000000-0000-4000-8000-000000000114', 'PHILVIEWS #14 authorized production import', now(), '9031274526', '{"source_file":"Philbo_August_Nov2026.csv","source_row":7,"product_slug":"phi111126206","direct_product_url":"https://philbodistribution.com/philbo-catalog/p/phi11