  ('82e7ab35-0807-4e76-a51a-ed37259c5bee', 'af0a46f8-e54b-4452-aac4-3a689188ec39', '14000000-0000-4000-8000-000000000014', 'PHI-111126-212', '6001579790', 'Daisy Cassidy #1 of 5', 'Daisy Cassidy', '1', null, 'Cover by Eryn Tompsett', 'English', 'Standard Floppy Comic', 'Limited/Mini-Series', 'DaisyCassidy', 'Monthly', 'E – Everyone 5+ Suitable for all audiences', 499, 'Daisy Cassidy is a space adventurer! She has been given the all important mission of staying home and babysitting her little brother, Mikey. But Mikey is immediately abducted by aliens, sending Daisy off on an adventure to find her brother, rescue him and bring him back home before her parents find out!', 'While Daisy pursues her brother''s abductors, she encounters another Rocket piloted by an alien named Kwerc. The abductors cause Daisy and Kwerc to crash land on a nearby planet while they escape, forcing daisy and Kwerc to work together if they are ever going to get off this planet.', 'Nicholas Doan', 'Eryn Tompsett', 'Eryn Tompsett', 'YAF010030', 'YAF010050', 'YAF010000', 24, 'Full Color', 6.875, 10.44, 1.6, false, 1, true, 'Sci-Fi', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor), (select user_id from pg_temp.philbo_import_actor), '14000000-0000-4000-8000-000000000114', 'PHILVIEWS #14 authorized production import', now(), '6001579790', '{"source_file":"Philbo_August_Nov2026.csv","source_row":13,"product_slug":"phi111126212","direct_product_url":"https://philbodistribution.com/philbo-catalog/p/phi111126212","source_barcode":"6001579790","source_printing_number":1,"imported_catalog_record":true,"authorized_import":"PHILVIEWS #14"}'::jsonb, false, false, 'https://drive.google.com/thumbnail?id=14oF03De2P7BbG_QMom4DoqYoGr4VVzrk&sz=w1600', null, null),
