  ('d33acfde-1a3e-4f7d-9461-5d19a005d4f8', 'b742240d-17d7-48ad-9477-dbd192326faf', '14000000-0000-4000-8000-000000000014', 'PHI-111126-218', '85008822805200111', 'TeamD A Little Big Adventure', 'TeamD', '#1', null, 'Main Cover', 'English', 'Standard Floppy Comic', 'One Shot', '228052', 'One-Shot', 'E – Everyone 5+ Suitable for all audiences', 499, null, 'Meet TeamD, led by Dee, our super-smart hero, who stumbles upon a diabolic plot by the Boogeyman to take over reality using the lost universe keys - known as Adinkras. 
