  ('ad46681f-4b07-400b-91d1-7aa2be3e25dc', 'b774447e-2ec1-4d57-bd06-98bea11d2b3e', '14000000-0000-4000-8000-000000000014', 'PHI-111126-250', '9781613451229', 'The Story of the Phantom: The Complete Avon Novels Volume 3 The Scorpia Menace', 'The Story of the Phantom: The Complete Avon Novels', '3', null, 'George Wilson cover', 'English', 'Prose Book', 'Limited/Mini-Series', null, 'Bi-Monthly', 'T – Teen 13+', 1499, 'This series reprints the original Phantom novels published by Avon Books. Stories cover various timelines of the history of the Phantom.', 'Volume 3 offers the classic Lee Falk tale: ""The Scorpia Menace!""  Famed artist George Wilson (Dr. Solar, Magnus Robot Fighter, The Phantom) painted the cover for Volume 4 as he did with all of the covers used for the Avon series, and they are reproduced beautifully to keep all of the details from the original books intact for a new generation of Phans to enjoy!  When her historical research brings her too close to the truth, Diana Palmer finds herself in deadly peril, and The Phantom moves into action to save his sweetheart and rout his ancient enemy.  Is it possible that the same notorious pirate band that confronted The Phantom four centuries ago has survived into the present day?', 'Lee Falk', 'none', 'George Wilson', 'FIC002000', null, null, 128, 'Black and White', 6, 9, 4, true, 1, true, 'Action/Adventure', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor), (select user_id from pg_temp.philbo_import_actor), '14000000-0000-4000-8000-000000000114', 'PHILVIEWS #14 authorized production import', now(), '9781613451229', '{"source_file":"Philbo_August_Nov2026.csv","source_row":51,"product_slug":"phi111126250","direct_product_url":"https://philbodistribution.com/philbo-catalog/p/phi111126250","source_barcode":"9781613451229","source_printing_number":1,"imported_catalog_record":true,"authorized_import":"PHILVIEWS #14"}'::jsonb, true,