  ('1ba11d11-61b7-4118-9ed9-127c01171139', 'b774447e-2ec1-4d57-bd06-98bea11d2b3e', '14000000-0000-4000-8000-000000000014', 'PHI-111126-251', '9781613451267', 'The Story of the Phantom: The Complete Avon Novels Volume 4 The Veiled Lady', 'The Story of the Phantom: The Complete Avon Novels', '4', null, 'George Wilson', 'English', 'Prose Book', 'Limited/Mini-Series', null, 'Bi-Monthly', 'T – Teen 13+', 1499, 'This series reprints the original Phantom novels published by Avon Books. Stories cover various timelines of the history of the Phantom.', 'Volume 4 offers the classic Lee Falk tale: ""The Veiled Lady."" Famed artist George Wilson (Dr. Solar, Magnus Robot Fighter, The Phantom) painted the cover for Volume #3 as he did with all of the covers used for the Avon series, and they are reproduced beautifully to keep all of the details from the original books intact for a new generation of Phans to enjoy!  Rising out of the jungles of Bangalla, shrouded by mists and superstitions, is the volcano known as THE VEILED LADY. What is the mystery of THE VEILED LADY? What secrets does she hide from the world? Precious treasure? Unimaginable danger? Many have died trying to find out.  Beautiful blonde Jan Love and her companions do find the astounding truth in earth shaking violence that presents a unique challenge even to the PHANTOM.', 'Lee Falk', 'none', 'George Wilson', 'FIC002000', null, null, 144, 'Black and White', 6, 9, 4, true, 1, true, 'Action/Adventure', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor), (select user_id from pg_temp.philbo_import_actor), '14000000-0000-4000-8000-000000000114', 'PHILVIEWS #14 authorized production import', now(), '9781613451267', '{"source_file":"Philbo_August_Nov2026.csv","source_row":52,"product_slug":"phi111126251","direct_product_url":"https://philbodistribution.com/philbo-catalog/p/phi111126251","source_barcode":"9781613451267","source_printing_n