  ('6fcfa738-7a9a-416a-8d98-e4658d688b39', 'b774447e-2ec1-4d57-bd06-98bea11d2b3e', '14000000-0000-4000-8000-000000000014', 'PHI-111126-252', '9781613451427', 'The Story of the Phantom: The Complete Avon Novels Volume 5 The Golden Circle', 'The Story of the Phantom: The Complete Avon Novels', '5', null, 'George Wilson', 'English', 'Prose Book', 'Limited/Mini-Series', null, 'Bi-Monthly', 'T – Teen 13+', 1499, 'This series reprints the original Phantom novels published by Avon Books. Stories cover various timelines of the history of the Phantom.', 'Volume 5 offers the tale: ""The Golden Circle!""  Famed artist George Wilson (Dr. Solar, Magnus Robot Fighter, The Phantom) painted the cover for Volume 5 as he did with all of the covers used for the Avon series, and they are reproduced beautifully to keep all of the details from the original books intact for a new generation of Phans to enjoy!  Accused of robbery and murder, The Phantom fights to find the real killers and solve the astounding secret of The Golden Circle! He also learns the truth in the old adage “The female is deadlier than the male.”', 'Lee Falk', 'none', 'George Wilson', 'FIC002000', null, null, 128, 'Black and White', 6, 9, 4, true, 1, true, 'Action/Adventure', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor), (select user_id from pg_temp.philbo_import_actor), '14000000-0000-4000-8000-000000000114', 'PHILVIEWS #14 authorized production import', now(), '9781613451427', '{"source_file":"Philbo_August_Nov2026.csv","source_row":53,"product_slug":"phi111126252","direct_product_url":"https://philbodistribution.com/philbo-catalog/p/phi111126252","source_barcode":"9781613451427","source_printing_number":1,"imported_catalog_record":true,"authorized_import":"PHILVIEWS #14"}'::jsonb, true, false, 'https://drive.google.com/thumbnail?id=17ieD0ThpIvoTge3BfzGeoJPudMSX72ut&sz=w1600', null, null),
  ('2c144300-8df5-4e86-a168-9fb9eb57ca31', 'b774447e-2ec1-4d57-bd06-98bea11d2b3e', '14000000-0000-4000-8000-000000000014', 'PHI-111126-253', '9781613450253', 'Mickey Spillane''s From the Files of...Mike Hammer: The complete Dailies and Sundays', null, null, null, 'Ed Robbins', 'English', 'Hardcover', 'One Shot', null, 'One-Shot', 'T – Teen 13+', 4999, 'America’s most well-known, hardboiled detective, Mike Hammer, returns with Hermes Press’ complete archival reprint of the entire continuity, From the Files of... Mike Hammer! Reprinting all of the dailies and Sunday strips (in digitally reconstructed color) this book will be the final word on this pop culture icon. The strip, which was distributed to newspapers by the Phoenix Features Syndicate, ran for only one year (1953-1954) — but what a year it was!', '"America’s most well-known, hardboiled detective, Mike Hammer, returns with Hermes Press’ complete archival reprint of the entire continuity, From the Files of... Mike Hammer! Reprinting all of the dailies and Sunday strips (in digitally reconstructed color) this book will be the final word on this pop culture icon. The strip, which was distributed to newspapers by the Phoenix Features Syndicate, ran for only one year (1953-1954) — but what a year it was! The strip is pure Mickey Spillane and was crafted under his watchful eye with art by Ed Robbins. The feature has everything fans of Mike Hammer would expect: Mike, Zelda, good girls, bad girls, gun-play, and lots of action!
