  ('1e616d8a-964b-43dc-bffe-dc6b642a2a28', '2e2ddf1e-099c-45ce-b62d-049d01667d81', '14000000-0000-4000-8000-000000000014', 'PHI-111126-273', '64462550101800011', 'Twilight Grimm full set 1-4', 'Twilight Grimm', '1-4', null, 'Rob Davis', 'English', 'Standard Floppy Comic', 'Limited/Mini-Series', 'vam', 'One-Shot', 'T – Teen 13+', 1996, 'The dark town of Hallowed Heights is a city divided by a massive wall. On one side of the wall live the middle and upper classes, living lives of mundane normalcy. But on the other side of the wall dwell the poor, the dispossessed…and the vampires. And all that stands between the living and their undead predators — is the brooding, violent young man named Twilight Grimm!', 'The dark town of Hallowed Heights is a city divided by a massive wall. On one side of the wall live the middle and upper classes, living lives of mundane normalcy. But on the other side of the wall dwell the poor, the dispossessed…and the vampires. And all that stands between the living and their undead predators — is the brooding, violent young man named Twilight Grimm!', 'R.A. Jones', 'Rob Davis', 'Rob Davis', 'CGN000000', 'CGN016000', null, 488, 'Full Color', 7, 10.5, 9, false, null, false, 'Supernatural, horror', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor), (select user_id from pg_temp.philbo_import_actor), '14000000-0000-4000-8000-000000000114', 'PHILVIEWS #14 authorized production import', now(), '64462550101800011', '{"source_file":"Philbo_August_Nov2026.csv","source_row":74,"product_slug":"phi111126273","direct_product_url":"https://philbodistribution.com/philbo-catalog/p/phi111126273","source_barcode":"64462550101800011","source_printing_number":null,"imported_catalog_record":true,"authorized_import":"PHILVIEWS #14"}'::jsonb, false, false, 'https://drive.google.com/thumbnail?id=1zp2PH38zosP8q6554-JSCdTz2ntummV_&sz=w1600', null, null),
  ('44ef4459-3953-4e31-868c-73eb23bddcbf', '2e2ddf1e-099c-45ce-b62d-049d01667d81', '14000000-0000-4000-8000-000000000014', 'PHI-111126-274', '9798188104573', 'Trumps tpb', 'Trumps', null, null, 'Peter Clinton', 'English', 'Graphic Novel', 'One Shot', 'scif-fi/superhero', 'One-Shot', 'T – Teen 13+', 1799, 'Four kingdoms exist on the sci-fi world called The Deck. Only one of those kingdoms can hold the seat of power; that kingdom is called Trumps. The Diamonds have held the seat of power since the last shuffle but the King of Clubs is waging war to wrest that power from the Diamonds so the Clubs can be trumps. The Queen of Diamonds is sick and on her deathbed, distracting the king from the war. Meanwhile, the Spades and Hearts are powerless and sitting out the fight…or are they? The Queen of Spades is working to convince the Jack of Diamonds to dethrone his king, and then they can unite Diamonds and Spades and become Trumps. Trumps is Game of Thrones meets Lord of the Rings with a sci-fi twist.', 'Four kingdoms exist on the sci-fi world called The Deck. Only one of those kingdoms can hold the seat of power; that kingdom is called Trumps. The Diamonds have held the seat of power since the last shuffle but the King of Clubs is waging war to wrest that power from the Diamonds so the Clubs can be trumps. The Queen of Diamonds is sick and on her deathbed, distracting the king from the war. Meanwhile, the Spades and Hearts are powerless and sitting out the fight…or are they? The Queen of Spades is working to convince the Jack of Diamonds to dethrone his king, and then they can unite Diamonds and Spades and become Trumps. Trumps is Game of Thrones meets Lord of the Rings with a sci-fi twist.', 'Roland Mann', 'various', 'Peter Clinton', 'COM000000', 'COM032000', 'CGN004070', 90, 'Full Color', 7, 10.5, 8, false, null, true, 'Sci-fi/Superhero', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor