  ('faedca8a-dd66-41e6-8f81-e816f37171d7', '2e2ddf1e-099c-45ce-b62d-049d01667d81', '14000000-0000-4000-8000-000000000014', 'PHI-111126-275', '64462550199500311', 'Silverline Christmas Special #3', 'Silverline Christmas Special', '3', null, 'Javier Lugo', 'English', 'Standard Floppy Comic', 'Ongoing', 'Christmas', 'Irregular', 'T – Teen 13+', 550, 'Annual publication of Christmas stories as Silverline spotlights both popular and new characters in holiday setting.', 'The Christmas Spirit is alive and well in 2026 with Silverline annual Christmas Special. This year features DEMON from the popular CAT & MOUSE series, SILVER DOLLAR and TEMPEST from SILVERSTORM, and MS. FURY from the upcoming special with her. In DEMON TAILS, Demon proves that the spirit of Christmas is alive and well, even the day after Christmas. By Dante Barry (writer), Cem Dayioglu (penciller), Thomas Florimonte (inker), and Roberta Conroy (colorist). Santa needs the help of Silver Dollar and Tempest when his sled gives out in a tale brought to you by John Metych, III (writer), Jaxon Renick (artist), Roberta Conroy (colorist). New to New Orleans, broke Ms. Fury struggles to find the right gift in a story brought to you by Roland Mann (writer) and Javier Lugo (penciller).', 'Barry, Mann, Metych', 'Dayioglu, Lugo, Renick', 'Javier Lugo', 'COM000000', 'COM015000', 'COM037000', 24, 'Full Color', 7, 10.5, 4.8, false, null, true, 'Superhero', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor), (select user_id from pg_temp.philbo_import_actor), '14000000-0000-4000-8000-000000000114', 'PHILVIEWS #14 authorized production import', now(), '64462550199500311', '{"source_file":"Philbo_August_Nov2026.csv","source_row":76,"product_slug":"phi111126275","direct_product_url":"https://philbodistribution.com/philbo-catalog/p/phi111126275","source_barcode":"64462550199500311","source_printing_number":null,"imported_catalog_record":true,