  ('a41b6d51-b5ec-4a77-9df1-f59d2059e3b6', '82028526-e6a8-42b8-b26e-86cfb9e991a8', '15000000-0000-4000-8000-000000000015', 'PHI121626-206', '63760992214500311', 'COLD KUTTER #3 variant cover A', 'COLD KUTTER', '3', '1', 'Cover art by Charles W Morgan. Colors Jesse Heagy', 'English', 'Standard Floppy Comic', 'Limited/Mini-Series', null, 'Monthly', 'M – Mature 17+ For mature audiences, contains strong content', 499, 'COLD KUTTER is a crime noir thriller with twists and turns as clues are discovered about the drug syndicate leader’s identity.  Private investigator Dillon Kutter comes under attack and his brother and partner is murdered by the syndicate. Dillon and his sidekick must stop the syndicate before the streets run with blood.  A murder revenge tale set in modern Manhattan.', 'Dillon and Trif have gone through a dramatic upheaval while their lives have been turned upside down. Get a peek inside the drug syndicate and find out why they want Dillon dead. It all happens in the explosive pages of COLD KUTTER #3 right here in your hands!', 'Charles W Morgan', 'Charles W Morgan', 'Charles W Morgan', 'CGN004010', 'CGN018000', null, 24, 'Black and White', 6.625, 10.25, 2.32, false, 1, true, 'Crime noir', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor), (select user_id from pg_temp.philbo_import_actor), '15000000-0000-4000-8000-000000000115', 'PHILVIEWS #15 authorized production import', now(), '63760992214500311', '{"source_file":"Philbo_Sept1catalog - Form Responses 1.csv","source_row":7,"product_slug":"phi121626206","direct_product_url":"https://philbodistribution.com/philbo-catalog/p/phi121626206","source_barcode":"63760992214500311","source_printing_number":1,"imported_catalog_record":true,"authorized_import":"PHILVIEWS #15"}'::jsonb, true, false, 'https://drive.google.com/thumbnail?id=1SPpUaT-V94h-9dnlzsmqQAddCFBeQe0T&sz=w1600', 'https://drive.google.com/thumbnail?id=1VFXtNyLuLbiTBGBGeMpknEk2bYxj2LCW&sz=w1600', null),
  ('c25fdf13-3d5d-47e4-b966-81e5b919f29d', '02466c1d-4e5a-4d57-908d-c7ff97599d91', '15000000-0000-4000-8000-000000000015', 'PHI121626-207', '9798988986294', 'Alpha Red #9 (Cover A)', 'Alpha Red', null, 'Cover A', 'Cover A/ James Q. Nguyen', 'English', 'Standard Floppy Comic', 'Ongoing', 'AlphaRed-9A-StarCrossComics', 'Monthly', 'E – Everyone 5+ Suitable for all audiences', 499, 'This SUPER hero’s-journey follows ordinary contractor Calvin “Wes” Wesley as he finds himself called into the eternal battle between good and evil, becoming ALPHA RED!  Forty years ago, Satan was betrayed by his right-hand demon and cast into the body of a human, then cursed with immortality.  The Devil has been walking the earth for four decades plotting his revenge, but no one knows who he is or what he looks like.  Our hero gets a chip implanted in his brain that makes him super-strong, super-fast, and super-smart.  Wes must find the Enemy and stop him from taking over the world.  A cross between the Marvel Cinematic Universe, G.I. Joe, and Transformers, this story will make you laugh and make you cry.  It will have you routing for Alpha Red to find the strength to stop Satan and save the world!', 'Alpha Red finds himself in hot water with Peter, the Kingdom''s senior leader. Thinking he has a few days off to enjoy Christmas, he''s quickly reminded that evil never takes a holiday.
