  ('0396ccda-383d-4db3-bbb3-5be887c7d2d1', '82028526-e6a8-42b8-b26e-86cfb9e991a8', '15000000-0000-4000-8000-000000000015', 'PHI121626-214', '63760992214500341', 'COLD KUTTER #3 cover variant D', 'Cold Kutter', '3', '4', 'Cover art by Francesco Tomaselli', 'English', 'Standard Floppy Comic', 'Limited/Mini-Series', null, 'Monthly', 'M – Mature 17+ For mature audiences, contains strong content', 499, null, 'Dillon and Trif have gone through a traumatic upheaval as their lives have been thrust upside down.  Attacks have made investigation almost impossible.  Get a peep into the drug syndicate and why they want Dillon dead! It happens here in Cold Kutter #3!', 'Charles W Morgan', 'Charles W Morgan', 'Francesco Tomaselli', 'CGN004010', 'CGN018000', null, 24, 'Black and White', 6.625, 10.25, 2.4, false, 1, true, 'Crime Noir', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor), (select user_id from pg_temp.philbo_import_actor), '15000000-0000-4000-8000-000000000115', 'PHILVIEWS #15 authorized production import', now(), '63760992214500341', '{"source_file":"Philbo_Sept1catalog - Form Responses 1.csv","source_row":15,"product_slug":"phi121626214","direct_product_url":"https://philbodistribution.com/philbo-catalog/p/phi121626214","source_barcode":"63760992214500341","source_printing_number":1,"imported_catalog_record":true,"authorized_import":"PHILVIEWS #15"}'::jsonb, true, false, 'https://drive.google.com/thumbnail?id=10JJZ5W5R9Fl5lLuKpv3Xujhy10NAiEk0&sz=w1600', 'https://drive.google.com/thumbnail?id=1gFFo1G5M6oOUHK791BYTt8tzJ7p47ggV&sz=w1600', null),
  ('3ae33cbe-cee6-4654-bafb-e5891d5cdd6c', 'b774447e-2ec1-4d57-bd06-98bea11d2b3e', '15000000-0000-4000-8000-000000000015', 'PHI121626-215', '9781613453315', 'PHANTOM HC VOL 36 THE COMPLETE NEWSPAPER DAILIES 1993-1994', 'The Phantom: The Complete Newspaper Dailies', '36', null, 'Sy Barry', 'English', 'Hardcover', 'Ongoing', null, 'Quarterly', 'T – Teen 13+ Suitable for teens, mild themes', 6500, '"Referred to by comic strip historian Maurice Horn as the “granddaddy of all costumed superheroes,” The Phantom was created in 1936 by Lee Falk. The strip hit the funny pages of newspapers well before the Dark Knight or Superman made their first appearances and has been acknowledged as an influence on every “masked man of mystery” since. The Phantom set the standard for action, adventure, intrigue, and romance in adventure comic strips and comic books — it has frequently been copied but never equaled.', '"Referred to by comic strip historian Maurice Horn as the “granddaddy of all costumed superheroes,” The Phantom was created in 1936 by Lee Falk. The strip hit the funny pages of newspapers well before the Dark Knight or Superman made their first appearances and has been acknowledged as an influence on every “masked man of mystery” since. The Phantom set the standard for action, adventure, intrigue, and romance in adventure comic strips and comic books — it has frequently been copied but never equaled. 
  This exciting 36th volume concludes the SY BARRY YEARS and ends with “The Phantom Cowboy,” credited to Sy and George Olesen and Keith Williams. Reprinted in all its black and white glory, journey with Hermes Press as we bring you five complete continuities drawn by Sy himself — and an assist in the last continuity, which continues the adventures of The Phantom, Diana, and his two children. Included in this volume are the following stories: The Moxley Awards (4/8 – 6/19/93); Nukes (6/21-11/13/93); Dinosaur (11/15/93 -2/12/94); The Plotters (2/14 -6/4/94) and The Phantom Cowboy (6/6 -12/17/94). Also included is a comprehensive essay, Sy Barry original artwork, and more."', 'Lee Falk', 'Sy Barry ; George Olesen ; Keith WIlliams', 'Sy Barry', 'CGN004080', null, null, 304, 'Black and White', 11.75, 8.25, 128, true, 1, true, 'Action/Adventure', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor), (select user_id from pg_temp.philbo_import_actor), '15000000-0000-4000-8000-000000000115', 'PHILVIEWS #15 authorized production import', now(), '9781613453315', '{"source_file":"Philbo_Sept1catalog - Form Responses 1.csv","source_row":16,"product_slug":"phi121626215","direct_product_url":"https://philbodistribution.com/philbo-catalog/p/phi121626215","source_barcode":"9781613453315","source_printing_number":1,"imported_catalog_record":true,"authorized_import":"PHILVIEWS #15"}'::jsonb, true, false, 'https://drive.google.com/thumbnail?id=1BmZumESV_lh97L8wLfNXMfr2NoxOT9T4&sz=w1600', null, null),
  ('532d9dfd-edb6-445b-9720-3ee396d27d96', 'b774447e-2ec1-4d57-bd06-98bea11d2b3e', '15000000-0000-4000-8000-000000000015', 'PHI121626-216', '9781613451441', 'Story of the Phantom: The Complete Avon Novels Volume 6 The Mysterious Ambassador', 'Story of the Phantom: The Complete Avon Novels', '6', null, 'George Wilson', 'english', 'Prose Book', 'Limited/Mini-Series', null, 'Bi-Monthly', 'T – Teen 13+ Suitable for teens, mild themes', 1499, 'Complete reprint of the original Avon series, and covers by George Wilson are reproduced  to keep all of the details from the original books intact for a new generation of Phans to enjoy!', 'This exciting installment, Volume 6 offers the tale: ""The Mysterious Ambassador!""  Famed artist George Wilson (Dr. Solar, Magnus Robot Fighter, The Phantom) painted the cover for Volume #6 as he did with all of the covers used for the Avon series, and they are reproduced beautifully to keep all of the details from the original books intact for a new generation of Phans to enjoy!  Why does a powerful General tremble at the sight of a simple mark? Can 50,000 soldiers protect him from that mark of The Phantom – the Sign of the Skull?  One man, fighting to save a new nation, and his beautiful sweetheart, Diana Palmer. One man matched against the armed might of the Dictator. Not an uneven match when that one man is The Phantom – the Ghost Who Walks.', 'Lee Falk', 'na', 'George Wilson', 'FIC002000', null, null, 144, 'Black and White', 6, 9, 4, true, 1, true, 'action/adventure', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor), (select user_id from pg_temp.philbo_import_actor), '15000000-0000-4000-8000-000000000115', 'PHILVIEWS #15 authorized production import', now(), '9781613451441', '{"source_file":"Philbo_Sept1catalog - Form Responses 1.csv","source_row":17,"product_slug":"phi121626216","direct_product_url":"https://philbodistribution.com/philbo-catalog/p/phi121626216","source_barcode":"9781613451441","source_printing_number":1,"imported_catalog_record":true,"authorized_import":"PHILVIEWS #15"}'::jsonb, true, false, 'https://drive.google.com/thumbnail?id=1wPQqD9HPCpJUC1s_A4Yg2lAkbApNszGI&sz=w1600', null, null),
  ('7f27651e-cac2-4e8f-ba26-3a5d681547cc', 'b774447e-2ec1-4d57-bd06-98bea11d2b3e', '15000000-0000-4000-8000-000000000015', 'PHI121626-217', '9781613451458', 'Story of the Phantom: The Complete Avon Novels Volume 7 The Mystery of the Sea Horse', 'Story of the Phantom: The Complete Avon Novels', '7', null, 'George Wilson', 'english', 'Prose Book', 'Limited/Mini-Series', null, 'Bi-Monthly', 'T – Teen 13+ Suitable for teens, mild themes', 1499, 'Complete reprint of the original Avon series, and covers by George Wilson are reproduced  to keep all of the details from the original books intact for a new generation of Phans to enjoy!', 'Volume 7 offers the tale: ""The Mystery of The Sea Horse!""  Famed artist George Wilson (Dr. Solar, Magnus Robot Fighter, The Phantom) painted the cover for Volume #7 as he did with all of the covers used for the Avon series, and they are reproduced beautifully to keep all of the details from the original books intact for a new generation of Phans to enjoy!   A palatial 200 foot yacht, “The Sea Horse” – a luxurious private island guarded by fierce dogs – all the property of the suave and charming Chris Danton.  What is the source of his seemingly inexhaustible wealth? What is the grim secret behind the “ageless” smile of the master of The Sea Horse?  The Phantom''s sweetheart, beautiful Diana Palmer, innocently stumbles into Danton''s web and finds herself caught up in an evil conspiracy from which she can be saved only by the power and ingenuity of the Phantom – The Ghost Who Walks.', 'Lee Falk', 'na', 'George Wilson', 'FIC002000', null, null, 144, 'Black and White', 6, 9, 4, true, 1, true, 'action/adventure', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor), (select user_id from pg_temp.philbo_import_actor), '15000000-0000-4000-8000-000000000115', 'PHILVIEWS #15 authorized production import', now(), '9781613451458', '{"source_file":"Philbo_Sept1catalog 