  ('7a6abeff-88a1-45e3-8292-2b6a2e0d771a', 'b774447e-2ec1-4d57-bd06-98bea11d2b3e', '15000000-0000-4000-8000-000000000015', 'PHI121626-218', '9781613451465', 'Story of the Phantom: The Complete Avon Novels Volume 8 The Hydra Monster', 'Story of the Phantom: The Complete Avon Novels', '8', null, 'George Wilson', 'english', 'Prose Book', 'Limited/Mini-Series', null, 'Bi-Monthly', 'T – Teen 13+ Suitable for teens, mild themes', 1499, 'Complete reprint of the original Avon series, and covers by George Wilson are reproduced  to keep all of the details from the original books intact for a new generation of Phans to enjoy!', 'This exciting installment, Volume 8 offers the tale: ""The Hydra Monster!""  Famed artist George Wilson (Dr. Solar, Magnus Robot Fighter, The Phantom) painted the cover for Volume #8 as he did with all of the covers used for the Avon series, and they are reproduced beautifully to keep all of the details from the original books intact for a new generation of Phans to enjoy!  What is the meaning of HYDRA – a mysterious evil that spans oceans and continents? Who are the black clad men– with V''s tattooed on shaven skulls – who appear in the wake of wars, earthquakes, fires, and other catastrophes?  The final mumbled words of a dying man draw the PHANTOM into an amazing web of violence, crime, and murder – the web of THE HYDRA MONSTER.', 'Lee Falk', 'na', 'George Wilson', 'FIC002000', null, null, 144, 'Black and White', 6, 9, 4, true, 1, true, 'action/adventure', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor), (select user_id from pg_temp.philbo_import_actor), '15000000-0000-4000-8000-000000000115', 'PHILVIEWS #15 authorized production import', now(), '9781613451465', '{"source_file":"Philbo_Sept1catalog - Form Responses 1.csv","source_row":19,"product_slug":"phi121626218","direct_product_url":"https://philbodistribution.com/philbo-catalog/p/phi121626218","source_barcode":"9781613451465","source_printing_number":1,"imported_catalog_record":true,"authorized_import":"PHILVIEWS #15"}'::jsonb, true, false, 'https://drive.google.com/thumbnail?id=1CWTrKqo7J-xlYZi5wN_HO3xvXD9PWrtN&sz=w1600', null, null),
  ('245cd440-e792-465c-9519-d41fce4f9bb5', 'b774447e-2ec1-4d57-bd06-98bea11d2b3e', '15000000-0000-4000-8000-000000000015', 'PHI121626-219', '9781613451472', 'Story of the Phantom: The Complete Avon Novels Volume 9 The Killer''s Town', 'Story of the Phantom: The Complete Avon Novels', '9', null, 'George Wilson', 'english', 'Prose Book', 'Limited/Mini-Series', null, 'Bi-Monthly', 'T – Teen 13+ Suitable for teens, mild themes', 1499, 'Complete reprint of the original Avon series, and covers by George Wilson are reproduced  to keep all of the details from the original books intact for a new generation of Phans to enjoy!', 'This exciting installment, Volume 9 offers the classic Lee Falk tale: ""Killer’s Town!""  Famed artist George Wilson (Dr. Solar, Magnus Robot Fighter, The Phantom) painted the cover for Volume #9 as he did with all of the covers used for the Avon series, and they are reproduced beautifully to keep all of the details from the original books intact for a new generation of Phans to enjoy!  In the far reaches of the peaceful jungle, a notorious international criminal establishes KILLER’S TOWN, a haven for thieves and murderers from many nations. There, with their stolen diamonds, gold, and other precious loot, they find safe refuge from the forces of law and order and are free to pursue their dissolute lives, protected from arrest and punishment.    When a beautiful and innocent young girl is trapped in this evil place, the terrorists are confronts by a mysterious and seemingly all-powerful force represented by THE SIGN OF THE SKULL, as the Phantom, single-handed, pits himself against the vicious world of KILLER’S TOWN.', 'Lee Falk', 'na', 'George Wilson', 'FIC002000', null, null, 144, 'Black and White', 6, 9, 4, true, 1, true, 'action/adventure', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor), (select user_id from pg_temp.philbo_import_actor), '15000000-0000-4000-80