  ('7f344c64-d976-496a-acbc-a0e50faf90b5', 'b774447e-2ec1-4d57-bd06-98bea11d2b3e', '15000000-0000-4000-8000-000000000015', 'PHI121626-220', '9781613451601', 'Story of the Phantom: The Complete Avon Novels Volume 10 The Goggle-Eyed Pirates', 'Story of the Phantom: The Complete Avon Novels', '10', null, 'George Wilson', 'english', 'Prose Book', 'Limited/Mini-Series', null, 'Bi-Monthly', 'T – Teen 13+ Suitable for teens, mild themes', 1499, 'Complete reprint of the original Avon series, and covers by George Wilson are reproduced  to keep all of the details from the original books intact for a new generation of Phans to enjoy!', 'This exciting installment, Volume 10 offers the classic Lee Falk tale: ""Goggle-Eyed Pirates!""  Famed artist George Wilson (Dr. Solar, Magnus Robot Fighter, The Phantom) painted the cover for Volume #10 as he did with all of the covers used for the Avon series, and they are reproduced beautifully to keep all of the details from the original books intact for a new generation of Phans to enjoy!  On a luxury liner in mid-ocean, a gang of weird pirates suddenly appears – as if out of nowhere. They rob the ship’s vaults and passengers – then disappear just as mysteriously as they had come. How?   Piracy – to the Phantom – is like a red cape to a bull. For centuries – since the first Phantom’s father was killed by pirates – the Phantom has been the nemesis of pirates everywhere. Now, once more, the Phantom must meet that threat as he rallies to seek out and destroy the mysterious GOGGLE-EYED PIRATES.', 'Lee Falk', 'na', 'George Wilson', 'FIC002000', null, null, 144, 'Black and White', 6, 9, 4, true, 1, true, 'action/adventure', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor), (select user_id from pg_temp.philbo_import_actor), '15000000-0000-4000-8000-000000000115', 'PHILVIEWS #15 authorized production import', now(), '9781613451601', '{"source_file":"Philbo_Sept1catalog - Form Responses 1.csv","source_row":21,"product_slug":"phi121626220","direct_product_url":"https://philbodistribution.com/philbo-catalog/p/phi121626220","source_barcode":"9781613451601","source_printing_number":1,"imported_catalog_record":true,"authorized_import":"PHILVIEWS #15"}'::jsonb, true, false, 'https://drive.google.com/thumbnail?id=1M-ILNES-u0CbD8GKb3ylEKUtBO7ccrn3&sz=w1600', null, null),
  ('e5d8e776-a34f-4d77-9f89-bdbfd3b073a1', 'b774447e-2ec1-4d57-bd06-98bea11d2b3e', '15000000-0000-4000-8000-000000000015', 'PHI121626-221', '9781613453339', 'Johnny Hazard: The Newspaper Dailies Volume 14 1965-1966', 'Johnny Hazard: The Newspaper Dailies', '14', null, 'Frank Robbins', 'english', 'Hardcover', 'Ongoing', null, 'Quarterly', 'T – Teen 13+ Suitable for teens, mild themes', 5499, 'Frank Robbins’ masterpiece, one of the all-time greatest action/adventure newspaper comic strips, Johnny Hazard. See more trend-setting artwork by comics legend Frank Robbins in one of the most important adventure strips ever to grace newspapers.  Reproduced entirely from original King Features press proofs.', '"Frank Robbins’ masterpiece, one of the all-time greatest action/adventure newspaper comic strips, Johnny Hazard, returns with Volume Fourteen of the series! Continues the adventures of Johnny Hazard picking up the storyline where Volume Thirteen left off. See more trend-setting artwork by comics legend Frank Robbins in one of the most important adventure strips ever to grace newspapers.  Reproduced entirely from original King Features press proofs. The continuities presented in this volume are five knock-out stories which highlight Robbins'' storytelling talents.  Included continuities are:  Tell it to Telstar(3/22-6/5/65); Time Moves Backward (6/7-8/28/65); Operation Trojan Horse (8/30-11/20/65);  Rescue Inc.(11/22/65-2/21/66) and  The Many Faces of Harry Clay (2/21-5/7/66)."', 'Frank Robbins', 'Frank Robbins', 'Frank Robbins', 'CGN004080', null, null, 240, 'Black and White', 10, 6, 8, false, 1, true, 'action/adventure', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor), (select user_id from pg_temp.philbo_import_actor), '15000000-0000-4000-8000-000000000115', 'PHILVIEWS #15 authorized production import', now(), '9781613453339', '{"source_file":"Philbo_Sept1catalog - Form Responses 1.