  ('fc702e4a-2e3a-46ce-9cfa-7309736e4e10', 'b774447e-2ec1-4d57-bd06-98bea11d2b3e', '15000000-0000-4000-8000-000000000015', 'PHI121626-222', '9781613452981', 'The Phantom Coloring Book', null, null, null, 'Norman Rockwell homage', 'english', 'Coloring Book', 'One Shot', null, 'One-Shot', 'E – Everyone 5+ Suitable for all audiences', 1999, null, '"Imagine a classic Phantom coloring book... now there''s a nostalgic walk down memory lane featuring Phantom images from the comic strip, ready to be colored in — The Phantom: The
