  ('5fe77a90-f0a7-4d4a-9dcf-e2b6ed1760ea', 'b774447e-2ec1-4d57-bd06-98bea11d2b3e', '15000000-0000-4000-8000-000000000015', 'PHI121626-223', '9781613453032', 'Johnny Hazard: The Newspaper Dailies Volume 13  Offered Again', 'Johnny Hazard: The Newspaper Dailies', '13', null, 'Frank Robbins', 'english', 'Hardcover', 'Ongoing', null, 'Quarterly', 'T – Teen 13+ Suitable for teens, mild themes', 5499, 'Frank Robbins’ masterpiece, one of the all-time greatest action/adventure newspaper comic strips, Johnny Hazard. See more trend-setting artwork by comics legend Frank Robbins in one of the most important adventure strips ever to grace newspapers.  Reproduced entirely from original King Features press proofs.', 'The continuities presented in Volume 13 are: Mysterious Friend (October 14, 1963–January 4, 1964); A Gift for Florian (January 6–March 28, 1964); Extortion, Inc. (March 30–June 27, 1964); Traders in Death (June 29–September 19, 1964); Alphabet Soup (September 21–December 26, 1964); and Operation Beardles (December 28, 1964–March 20, 1965).', 'Frank Robbins', 'Frank Robbins', 'Frank Robbins', 'CGN018000', null, null, 240, 'Black and White', 10, 6, 48, false, 1, true, 'Action/Adventure', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor), (select user_id from pg_temp.philbo_import_actor), '15000000-0000-4000-8000-000000000115', 'PHILVIEWS #15 authorized production import', now(), '9781613453032', '{"source_file":"Philbo_Sept1catalog - Form Responses 1.csv","source_row":24,"product_slug":"phi121626223","direct_product_url":"https://philbodistribution.com/philbo-catalog/p/phi121626223","source_barcode":"9781613453032","source_printing_number":1,"imported_catalog_record":true,"authorized_import":"PHILVIEWS #15"}'::jsonb, true, false, 'https://drive.google.com/thumbnail?id=1MCQB3k4YykYtLt_RGViu_QIfxKa0GZyc&sz=w1600', null, null),
  ('c5af8b0d-5c93-4690-824e-2b8ce37c9d0a', 'b774447e-2ec1-4d57-bd06-98bea11d2b3e', '15000000-0000-4000-8000-000000000015', 'PHI121626-224', '9781613453100', 'The Phantom the Complete Dailies Volume 35 1991-1993 Offered Again', 'The Phantom Complete Dailies', '35', null, 'Vol 34 1991-1993 Sy Barry', 'english', 'Hardcover', 'Ongoing', null, 'Quarterly', 'T – Teen 13+ Suitable for teens, mild themes', 6500, 'Referred to by comic strip historian Maurice Horn as the “granddaddy of all costumed superheroes,” The Phantom was created in 1936 by Lee Falk. The strip hit the funny pages of newspapers well before the Dark Knight or Superman made their first appearances and has been acknowledged as an influence on every “masked man of mystery” since. The Phantom set the standard for action, adventure, intrigue, and romance in adventure comic strips and comic books — it has frequently been copied but never equaled.', '"Referred to by comic strip historian Maurice Horn as the “granddaddy of all costumed superheroes,” The Phantom was created in 1936 by Lee Falk. The strip hit the funny pages of newspapers well before the Dark Knight or Superman made their first appearances and has been acknowledged as an influence on every “masked man of mystery” since. The Phantom set the standard for action, adventure, intrigue, and romance in adventure comic strips and comic books — it has frequently been copied but never equaled. 
  This exciting 35th volume continues the SY BARRY YEARS! Reprinted in all its black and white glory, journey with Hermes Press as we bring you five complete continuities drawn by Sy himself which continue the adventures of The Phantom, Diana, and his two children: ” Also included is a comprehensive essay and documentary materials."', 'Lee Falk', 'Sy Barry', 'Sy Barry', 'CGN018000', null, null, 264, 'Black and White', 12.125, 8.5, 48, false, 1, true, 'Action/Adventure', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor), (select user_id from pg_temp.philbo_import_actor), '15000000-0000-4000-8000-000000000115', 'PHILVIEWS #15 authorized production import', now(), '9781613453100', '{"source_file":"Philbo_Sept1catalog - Form Responses 1.csv","source_row":25,"product_slug":"phi121626224","direct_product_url":"https://philbodistribution.com/philbo-catalog/p/phi121626224","source_barcode":"9781613453100","source_printing_number":1,"imported_catalog_record":true,"authorized_import":"PHILVIEWS #15"}'::jsonb, true, false, 'https://drive.google.com/thumbnail?id=16A68WUzDV5IECROtGufOc3-KKr3DvI-C&sz=w1600', null, null),
  ('4ae695ef-51c4-412e-85bd-fcda490dc9fb', 'af0a46f8-e54b-4452-aac4-3a689188ec39', '15000000-0000-4000-8000-000000000015', 'PHI121626-225', '6001579791', 'Daisy Cassidy #2 of 5', 'Daisy Cassidy', '2', null, 'Cover by Eryn Tompsett', 'English', 'Standard Floppy Comic', 'Limited/Mini-Series', 'DaisyCassidy', 'Monthly', 'E – Everyone 5+ Suitable for all audiences', 499, 'Daisy Cassidy is a space adventurer tasked with the all-important mission of... staying home and babysitting her little brother! But Mikey is immediately abducted by aliens! So daisy is off on an adventure to find her brother, rescue him and bring him back home before her parents find out!', 'Daisy and Kwerc are held captive by an alien trash collector that''s obsessed with theatre! He forces them to perform his favorite play. Does this sound weird to you? Well it sounds weird to Daisy and Kwerc too! They must escape and get back on the trail of their kidnapped siblings!', 'Nicholas Doan', 'Eryn Tompsett', 'Eryn Tompsett', 'JUV008140', 'JUV008110', 'JUV008040', 28, 'Full Color', 6.875, 10.44, 2.4, false, 1, true, 'Science Fiction', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor), (select user_id from pg_temp.philbo_import_actor), '15000000-0000-4000-8000-000000000115', 'PHILVIEWS #15 authorized production import', now(), '6001579791', '{"source_file":"Philbo_Sept1catalog - Form Responses 1.csv","source_row":26,"product_slug":"phi121626225","direct_product_url":"https://philbodistribution.com/philbo-catalog/p/phi121626225","source_barcode":"6001579791","source_printing_number":1,"imported_catalog_record":true,"authorized_import":"PHILVIEWS #15"}'::jsonb, false, false, 'https://drive.google.com/thumbnail?id=1u80n7jLnWn8beWZH9hsafqe0rBG55fin&sz=w1600', null, 'https://drive.google.com/thumbnail?id=1f2cXpgHfzEMEcDd2_-wFdtFbS1E1fmET&sz=w1600'),
