  ('7f4dcf54-8d86-44d3-85cf-318d2a23bb7a', 'b742240d-17d7-48ad-9477-dbd192326faf', '15000000-0000-4000-8000-000000000015', 'PHI121626-247', '86001432179500111', 'The Galactics #1 Cover A', 'The Galactics', '1', '1', 'Cover A', 'English', 'Standard Floppy Comic', 'Ongoing', '321795', 'Quarterly', 'T – Teen 13+ Suitable for teens, mild themes', 699, null, 'The world''s greatest heroes have banded together to fight enemies both foreign and domestic. A threat greater than anything they may have possibly faced is coming toward Earth. Do they have the power to stop it and save humanity? Issue #0 introduces the comic book world to the Galactics and recaps the history of the team from their humble beginnings to their current world-protecting status. We meet some key players in the story and set up storylines to come. All done in the nostalgic 80s art style.', 'Tom Aresto', 'Tom Aresto', 'Tom Aresto', 'CGN004080', null, null, 24, 'Full Color', 6.62, 10.25, 8, false, 1, true, 'Superheroes | Action & Adventure', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor), (select user_id from pg_temp.philbo_import_actor), '15000000-0000-4000-8000-000000000115', 'PHILVIEWS #15 authorized production import', now(), '86001432179500111', '{"source_file":"Philbo_Sept1catalog - Form Responses 1.csv","source_row":48,"product_slug":"phi121626247","direct_product_url":"https://philbodistribution.com/philbo-catalog/p/phi121626247","source_barcode":"86001432179500111","source_printing_number":1,"imported_catalog_record":true,"authorized_import":"PHILVIEWS #15"}'::jsonb, false, false, 'https://drive.google.com/thumbnail?id=1hD7p3oyag3vhrxQF3FYMpDF3wz32VFE3&sz=w1600', null, null),
