  ('4c88921d-5d1b-40ad-a79a-a54c088e9d52', 'b742240d-17d7-48ad-9477-dbd192326faf', '15000000-0000-4000-8000-000000000015', 'PHI121626-250', '86001432179500141', 'The Galactics #1 Cover D', 'The Galactics', 'The Galactics', '4', 'Cover D', 'English', 'Standard Floppy Comic', 'Ongoing', '321795', 'Quarterly', 'T – Teen 13+ Suitable for teens, mild themes', 699, null, 'The world''s greatest heroes have banded together to fight enemies both foreign and domestic. A threat greater than anything they may have possibly faced is coming toward Earth. Do they have the power to stop it and save humanity? Issue #0 introduces the comic book world to the Galactics and recaps the history of the team from their humble beginnings to their current world-protecting status. We meet some key players in the story and set up storylines to come. All done in the nostalgic 80s art style.', 'Tom Aresto', 'Tom Aresto', 'Tom Aresto', 'CGN004080', 'CGN018000', null, 24, 'Full Color', 6.62, 10.25, 8, false, 1, true, 'Superheroes | Action & Adventure', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor), (select user_id from pg_temp.philbo_import_actor), '15000000-0000-4000-8000-000000000115', 'PHILVIEWS #15 authorized production import', now(), '86001432179500141', '{"source_file":"Philbo_Sept1catalog - Form Responses 1.csv","source_row":51,"product_slug":"phi121626250","direct_product_url":"https://philbodistribution.com/philbo-catalog/p/phi121626250","source_barcode":"86001432179500141","source_printing_number":1,"imported_catalog_record":true,"authorized_import":"PHILVIEWS #15"}'::jsonb, false, false, 'https://drive.google.com/thumbnail?id=1JpiSIPuBnDzURfV8Z9NFeNuyM5UhrNtQ&sz=w1600', null, null),
  ('d19fec2e-5955-4df6-8e09-41eda8bc19a8', '2e2ddf1e-099c-45ce-b62d-049d01667d81', '15000000-0000-4000-8000-000000000015', 'PHI121626-251', '64462550289300211', 'Divinity #2', 'Divinity', '2', null, 'Mel Rubi', 'English', 'Standard Floppy Comic', 'Ongoing', 'YA', 'Quarterly', 'T – Teen 13+ Suitable for teens, mild themes', 499, 'Eleven-year-old Divinity Gray discovers she has the ability to heal. After her parents are mysteriously killed, her stepbrother Zach becomes her legal guardian. Unfortunately, others have discovered Divinity''s powers...and want it for themselves. Divinity and Zach must go on the run to keep Divinity safe.
“Divinity #1 manages to bring a fresh take to the story of a young girl with mysterious healing powers.”  - Kevin VanHook, film-maker and creator of ''Bloodshot''.
“It''s one of the moments that tells the reader a comic book has succeeded.  It''s the moment when the reader says, “Hey! That''s all I get right now?  What happens next?” -  Maggie Thompson, longtime editor of the news magazine Comics Buyer''s Guide', 'Their home invaded by armed militia, Divinity and Zach must fight their way out to safety. Enter Olivia Barnes, an old military buddy of Zach''s. Zach recruits Olivia to help, but trouble follows them as Mr. E''s goons find them. Will Zach be able to protect Vini from Mr. E?', 'R.A. Jones/Barb Kaalberg', 'Alex Sarabia', 'Mel Rubi', 'COM037000', 'CGN025000', 'COM015000', 24, 'Full Color', 6.75, 10.25, 4.8, false, null, true, 'superhero', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor), (select user_id from pg_temp.philbo_import_actor), '15000000-0000-4000-8000-000000000115', 'PHILVIEWS #15 authorized production import', now(), '64462550289300211', '{"source_file":"Philbo_Sept1catalog - Form Responses 1.csv","source_row":52,"product_slug":"phi121626251","direct_product_url":"https://philbodistribution.com/philbo-catalog/p/phi121626251","source_barcode":"64462550289300211","source_printing_number":null,"imported_catalog_record":true,"authorized_import":"PHILVIEWS #15"}'::jsonb, false, false, 'https://drive.google.com/thumbnail?id=1l1SA1fKfQJw2uNuREiYpUi0iyWFx5MLw&sz=w1600', null, 'https://drive.google.com/thumbnail?id=1dGq8Ym3UgI42uC0PuE-lyrlSKvRiqmjv&sz=w1600'),
  ('2df8a66e-5307-4259-b087-83824af3af18', '3c0724de-8fff-494c-98a4-0a6cfba76841', '15000000-0000-4000-8000-000000000015', 'PHI121626-252', '9781960171306', 'INTERTWINED: THE SPIRITS OF WUXING SAGA (10th Anniversary Edition)', 'INTERTWINED', null, null, 'Trade cover by Fred Pham Chuong', 'English', 'Hardcover', 'Collected', null, 'One-Shot', 'M – Mature 17+ For mature audiences, contains strong content', 3999, 'Juan Jin didn’t ask to be a hero. He only wanted to follow theway of Wing Chun and Jeet Kune Do, the Kung Fu styles he brilliantly masters...
Leah Ai Tian did not ask to fight for Justice. She only wanted to escape
a forced marriage and live  peacefully in the way of the Torah…
Antwan did not ask to be a refugee. But a Coup  in his native land of Haïti forced him to leave…
 
The Mighty Elements, the WuXing, and the Loas had other plans for them. 

It’s 1971. Welcome to the world of Intertwined.', 'This new 10th Anniversary hardcover gold edition collects INTERTWINED #1-6, INTERTWINED: THE LAST JEWISH DAUGHTER OF KAIFENG and INTERTWINED: THE TORCHBEARER, a 300 pages omnibus celebrating 10 years of Kung Fu Noir! Written by Fabrice Sapolsky with Greg Anderson Elysée and Ramon Gil. Featuring art from Fred Pham Chuong (Transformers), Domenico Carbone (Thundercats, Moon Knight) and guest artists OLIVIER COIPEL, ROLAND BOSCHI, GERALD PAREL, MATEUS SANTOLOUCO, PATRICK ZIRCHER, MEDHI CHEGGOUR , FEI CHEN, HO SENG HUI, NICK BRADSHAW, FRANCK UZAN and ENID BALAM.', 'Fabrice Sapolsky', 'Fred Pham Chuong, Domenico Carbone, Ho Seng hui, Fei Chen', 'Fred Pham Chuong', 'CGN004080', 'CGN004010', 'CGN019000', 300, 'Full Color', 5.5, 8.5, 16, true, null, true, 'Martial Arts/Superheroes/Noir', 'live', 'tbd', now(), now(), (select user_id from pg_temp.philbo_import_actor), now(), (select user_id from pg_temp.philbo_import_actor), (select user_id from pg_temp.philbo_import_actor), '15000000-0000-4000-8000-000000000115', 'PHILVIEWS #15 authorized production import', now(), '9781960171306', '{"source_file":"Philbo_Sept1catalog - Form Responses 1.csv","source_row":53,"product_slug":"phi121626252","direct_product_url":"https://philbodistribution.com/philbo-catalog/p/phi121626252","source_barcode":"9781960171306","source_printing_number":null,"imported_catalog_record":true,"authorized_import":"PHILVIEWS #15"}'::jsonb, true, false, 'https://drive.google.com/thumbnail?id=1cVnblMBk6lJTFvadRrg_mP4tHWnkTB3C&sz=w1600', null, null),
